#include "../../include/faster-blaster/vtable_autofill.h"
#include "../backends/backend_interface.h"
#include <stddef.h>

/* ============================================================================
 * BLAS Level 3: GEMM Wrappers (Standard Single-Matrix Operations)
 * ========================================================================= */

/* SGEMM - Single precision matrix multiply */
void fb_sgemm_from_unified(const fb_layout_t layout,
                           const fb_transpose_t transa,
                           const fb_transpose_t transb, const int64_t m,
                           const int64_t n, const int64_t k, const float alpha,
                           const float *A, const int64_t lda, const float *B,
                           const int64_t ldb, const float beta, float *C,
                           const int64_t ldc) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->gemm_unified) {
    return; /* Error: no vtable or no unified implementation */
  }

  /* Convert layout to transpose characters for unified API */
  char trans_a = (transa == FB_NO_TRANS) ? 'N'
                 : (transa == FB_TRANS)  ? 'T'
                                         : 'C';
  char trans_b = (transb == FB_NO_TRANS) ? 'N'
                 : (transb == FB_TRANS)  ? 'T'
                                         : 'C';

  vtable->gemm_unified(FB_PREC_FP32,    /* precision */
                       FB_BATCH_SINGLE, /* batch_mode */
                       FB_FUSION_NONE,  /* fusion */
                       trans_a, trans_b, (size_t)m, (size_t)n, (size_t)k,
                       &alpha, A, (size_t)lda,
                       0,                 /* strideA=0 (not used for single) */
                       B, (size_t)ldb, 0, /* strideB=0 */
                       &beta, C, (size_t)ldc, 0, /* strideC=0 */
                       NULL,                     /* bias (no fusion) */
                       FB_ACT_NONE,              /* activation */
                       1,                        /* batch_count=1 */
                       NULL                      /* stream (default) */
  );
}

