/* ============================================================================
 * Vtable Auto-Fill Function: Install GEMM Wrappers
 * ========================================================================= */

/**
 * @brief Fill missing GEMM entries in vtable from gemm_unified
 *
 * Called by fb_autofill_unified_to_specific() during plugin finalization.
 * Only installs wrappers for missing operations - doesn't overwrite existing
 * ones.
 */
void fb_autofill_gemm_from_unified(fb_backend_vtable_t *vtable) {
  if (!vtable || !vtable->gemm_unified) {
    return; /* No unified implementation available */
  }

  /* Install wrappers only if specific operations are missing */
  if (vtable->sgemm == NULL) {
    vtable->sgemm = fb_sgemm_from_unified;
  }

  if (vtable->dgemm == NULL) {
    vtable->dgemm = fb_dgemm_from_unified;
  }

  if (vtable->cgemm == NULL) {
    vtable->cgemm = fb_cgemm_from_unified;
  }

  if (vtable->zgemm == NULL) {
    vtable->zgemm = fb_zgemm_from_unified;
  }
}
